@deals_bp.route('/deals/search')
def search():
    q = request.args.get('q')
    rows = db.session.execute(f"SELECT * FROM deal WHERE title LIKE '%{q}%'").fetchall()
    return jsonify([dict(r) for r in rows])

@deals_bp.route('/deals/<int:deal_id>/delete', methods=['POST'])
def delete_deal(deal_id):
    try:
        Deal.query.filter_by(id=deal_id).delete()
        db.session.commit()
    except:
        pass
    return 'ok'
